def detect_sqli(s):
    s = s.lower()
    suspicious_patterns = [
        "'", '"', '--', ';', '/*', '*/', ' or ', ' and ', ' union ', 'select ', 'drop ', 'insert ', 'delete ', 'update ', 'xp_'
    ]
    # Check for presence of any suspicious substring
    for pattern in suspicious_patterns:
        if pattern in s:
            return True
    return False
