def detect_sqli(s):
    s = s.lower()
    suspicious_substrings = [
        "'", "--", ";", "/*", "*/", " or ", " and ",
        " union ", " select ", " insert ", " update ", " delete ",
        " drop ", " exec ", " xp_"
    ]
    # Simple heuristic: if input contains suspicious substrings, likely SQLi
    for sub in suspicious_substrings:
        if sub in s:
            return True
    return False

def detect_sqli(s: str) -> bool:
    s = s.lower()
    # Simple heuristic: look for common SQL injection patterns and keywords
    suspicious_patterns = [
        "'", '"', ";", "--", "/*", "*/",
        " or ", " and ", " union ", "select ", "insert ", "update ", "delete ", "drop "
    ]
    return any(pat in s for pat in suspicious_patterns)

